88	     * The owner's numeric membership level, assigned on creation. It starts at 1, gains
89	     * 1 when an email address is present, and gains 1 when the owner has no namesakes
90	     * (namesakeCount is 0), capped at 3. Level 4 is reserved for tenure.
91	     */
92	    default Integer membershipLevel(Owner owner) {
93	        int level = 1;
94	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
95	        if (hasEmail) {
96	            level++;
97	        }
98	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
99	        if (noNamesakes) {
100	            level++;
101	        }
102	        return Math.min(level, 3);
103	    }
