105	    /**
106	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
107	     * customerCode. Returns {@code null} when the customerCode has not been assigned.
108	     */
109	    default Integer checkDigit(Owner owner) {
110	        if (owner.getCustomerCode() == null) {
111	            return null;
112	        }
113	        String s = owner.getCustomerCode();
114	        int sum = 0;
115	        boolean dbl = true;
116	        for (int i = s.length() - 1; i >= 0; i--) {
117	            char c = s.charAt(i);
118	            if (c < '0' || c > '9') {
119	                continue;
120	            }
121	            int d = c - '0';
122	            if (dbl) {
123	                d *= 2;
124	                if (d > 9) {
125	                    d -= 9;
126	                }
127	            }
128	            sum += d;
129	            dbl = !dbl;
130	        }
131	        return (10 - (sum % 10)) % 10;
132	    }
